"""Cached method outputs under tools/testset/runs/<kind>/<clip>.npz (git-ignored, regenerated by the CLI scripts)."""
from __future__ import annotations

import json
from pathlib import Path

import numpy as np

import fa_eval  # noqa: F401
from testset_common import RUNS, clip_by_id, clip_path, load_manifest


def run_dir(kind: str) -> Path:
    d = RUNS / kind
    d.mkdir(parents=True, exist_ok=True)
    return d


def npz_path(kind: str, clip_id: str) -> Path:
    return run_dir(kind) / f"{clip_id}.npz"


def load_npz(kind: str, clip_id: str) -> dict:
    p = npz_path(kind, clip_id)
    if not p.exists():
        return {}
    z = np.load(p, allow_pickle=False)
    return {k: z[k] for k in z.files}


def save_npz(kind: str, clip_id: str, data: dict) -> None:
    p = npz_path(kind, clip_id)
    tmp = p.with_name(p.stem + ".tmp.npz")
    np.savez_compressed(tmp, **data)
    tmp.replace(p)


def clip_entry(clip_id: str) -> dict:
    return clip_by_id(load_manifest(), clip_id)


def clip_file(clip_id: str) -> Path:
    return clip_path(clip_entry(clip_id))


def json_default(o):
    if isinstance(o, (np.integer,)):
        return int(o)
    if isinstance(o, (np.floating,)):
        return float(o)
    if isinstance(o, np.ndarray):
        return o.tolist()
    raise TypeError(type(o))


def dump_json(path: Path, obj) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, indent=1, default=json_default, ensure_ascii=False) + "\n", encoding="utf-8")
